properties.query:
let windowSize = 4h;
let TrustedSrc = _GetWatchlist('Trusted_TI_Source_List') | project SourceId;
let posVarGate = toscalar(
    _GetWatchlist('UAV_Threshold_List')
    | where ThresholdKey == 'MaxPosHorizVariance'
    | project toreal(Value));
// S14: TI 소스 오염 시각 (전역 스칼라 — UAVId 컬럼 미존재 가능)
let S14_Time = toscalar(
    UAVThreatIntel_CL
    | where TimeGenerated > ago(windowSize)
    | where Source !in (TrustedSrc)
    | summarize min(TimeGenerated));
// S4: 펌웨어 HashMatch==0
let S4 =
    UAVPgse_CL
    | where TimeGenerated > ago(windowSize)
    | where HashMatch == 0 or SbomForbiddenCount > 0
    | where isnotnull(S14_Time) and TimeGenerated >= S14_Time and TimeGenerated <= S14_Time + 2h
    | project T2=TimeGenerated, UAVId=tostring(UAVId);
// S1: GNSS 스푸핑
let S1 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where MsgType == 'EKF_STATUS_REPORT'
    | where PosHorizVariance > posVarGate
    | project T3=TimeGenerated, UAVId=tostring(UAVId);
S4
| join kind=inner (S1) on UAVId
| where T3 >= T2 and T3 <= T2 + 2h
| extend T1 = S14_Time
| extend CampaignType = "C2_TI오염_펌웨어변조_GNSS스푸핑"
| extend StepSummary = strcat("S14@", tostring(T1), "→S4@", tostring(T2), "→S1@", tostring(T3))
| extend Severity = "High"
| project T1, T2, T3, UAVId, CampaignType, StepSummary, Severity
